:root {
  --bg: #f6f3ee;
  --card: #ffffff;
  --ink: #23312a;
  --muted: #6b7a70;
  --line: #e5e0d6;
  --brand: #d1451b;
  --brand-dark: #b23a15;
  --brand-soft: #fbe4db;
  --green: #2f8f5b;
  --green-soft: #e0f2e8;
  --yellow: #b7791f;
  --yellow-soft: #f8ead0;
  --blue: #2f6fb0;
  --blue-soft: #dce9f5;
  --grey: #6b7a70;
  --grey-soft: #ecebe6;
  --red: #c0392b;
  --red-soft: #f7e0dc;
  --radius: 14px;
  --shadow: 0 6px 24px rgba(35, 49, 42, 0.08);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 20px;
  background: #fff;
  border-bottom: 1px solid var(--line);
  box-shadow: 0 1px 0 rgba(0,0,0,0.02);
}

.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 1.15rem; }
.brand-icon { font-size: 1.5rem; }
.brand-name { letter-spacing: .3px; }

.userbox { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.userbox #userbox-name { font-weight: 700; }
.badge { font-size: .72rem; font-weight: 700; padding: 3px 9px; border-radius: 999px; background: var(--brand-soft); color: var(--brand-dark); text-transform: uppercase; letter-spacing: .5px; }
.badge.manager { background: var(--blue-soft); color: var(--blue); }

main { max-width: 1100px; margin: 0 auto; padding: 22px 16px 80px; }

/* Botões */
.btn { font: inherit; font-weight: 700; border: none; border-radius: 10px; padding: 11px 18px; cursor: pointer; transition: .15s; }
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--brand); color: #fff; }
.btn-primary:hover { background: var(--brand-dark); }
.btn-ghost { background: transparent; color: var(--ink); border: 1px solid var(--line); padding: 8px 14px; }
.btn-ghost:hover { background: #f3f0e9; }
.btn-sm { padding: 7px 12px; font-size: .9rem; }
.btn-danger { background: var(--red-soft); color: var(--red); }
.btn-danger:hover { background: var(--red); color: #fff; }
.btn:disabled { opacity: .5; cursor: not-allowed; }

/* Formulários */
label { display: block; font-size: .85rem; font-weight: 700; color: var(--muted); margin-bottom: 5px; }
input, select, textarea {
  font: inherit; width: 100%; padding: 11px 13px; border: 1px solid var(--line);
  border-radius: 10px; background: #fff; color: var(--ink);
}
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft); }
textarea { resize: vertical; min-height: 70px; }
.field { margin-bottom: 14px; }

/* Auth */
.auth-wrap { max-width: 440px; margin: 40px auto; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); }
.auth-card { padding: 28px; }
.auth-card h1 { margin: 0 0 4px; font-size: 1.6rem; }
.auth-card p.sub { margin: 0 0 22px; color: var(--muted); }
.tabs { display: flex; gap: 6px; background: #f3f0e9; padding: 5px; border-radius: 11px; margin-bottom: 20px; }
.tabs button { flex: 1; font: inherit; font-weight: 700; border: none; background: transparent; padding: 9px; border-radius: 8px; cursor: pointer; color: var(--muted); }
